def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    out = [row[:] for row in grid]

    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg:
                    continue

                # Only begin at the first cell of a diagonal run.
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                for er, ec, vr, vc in (
                    (run[0][0], run[0][1], -dr, -dc),
                    (run[-1][0], run[-1][1], dr, dc),
                ):
                    # Extend only from an endpoint isolated from other
                    # non-background cells by orthogonal adjacency.
                    if any(
                        0 <= er + ar < h and 0 <= ec + ac < w
                        and grid[er + ar][ec + ac] != bg
                        for ar, ac in ((1, 0), (-1, 0), (0, 1), (0, -1))
                    ):
                        continue

                    rr, cc = er + vr, ec + vc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += vr
                        cc += vc

    return out
